/// <reference lib="webworker" />
import { clientsClaim } from 'workbox-core';
import { precacheAndRoute, createHandlerBoundToURL } from 'workbox-precaching';
import { registerRoute, NavigationRoute } from 'workbox-routing';
import { StaleWhileRevalidate, CacheFirst } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';

declare const self: ServiceWorkerGlobalScope;

// Take over the clients immediately
clientsClaim();

// Precache all assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST);

// ----------------------------------------------------------------------------
// Navigation Fallback
// ----------------------------------------------------------------------------
// For SPA routing, serve index.html for all navigation requests,
// UNLESS they are API requests or Razorpay frames.
const navigationDenylist = [
  /^\/api\//,
  /^\/admin-api\//,
  /\/__/,
  /razorpay\.com/
];

const fallbackHandler = createHandlerBoundToURL('/index.html');
const offlineFallbackHandler = async (options: any) => {
  try {
    return await fallbackHandler(options);
  } catch (error) {
    return caches.match('/offline.html') as Promise<Response>;
  }
};

registerRoute(
  new NavigationRoute(offlineFallbackHandler, {
    denylist: navigationDenylist,
  })
);

// ----------------------------------------------------------------------------
// Runtime Caching
// ----------------------------------------------------------------------------

// 1. Public Content Allowlist (StaleWhileRevalidate)
// ONLY safe, non-personal data can be cached.
registerRoute(
  ({ url }) => url.pathname.match(/^\/api\/v1\/(pages|support\/config|support\/faqs|plans|services)/),
  new StaleWhileRevalidate({
    cacheName: 'public-content',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 24 * 60 * 60, // 24 hours
      }),
    ] as any[],
  })
);

// 2. Images & Fonts (CacheFirst)
registerRoute(
  ({ request }) => request.destination === 'image' || request.destination === 'font',
  new CacheFirst({
    cacheName: 'assets',
    plugins: [
      new CacheableResponsePlugin({
        statuses: [0, 200],
      }),
      new ExpirationPlugin({
        maxEntries: 80,
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 Days
      }),
    ] as any[],
  })
);

// Everything else (authenticated API routes, payments, etc.) will bypass the cache automatically.

// ----------------------------------------------------------------------------
// Message Handling (Update Flow)
// ----------------------------------------------------------------------------
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

// ----------------------------------------------------------------------------
// Web Push Notifications
// ----------------------------------------------------------------------------
self.addEventListener('push', (event) => {
  if (!event.data) return;

  try {
    const data = event.data.json();
    const title = data.title || 'Date to Go';
    const options = {
      body: data.body,
      icon: '/pwa-192x192.png',
      badge: '/favicon.svg',
      tag: data.tag || 'dtg-notification',
      data: {
        url: data.url || '/',
      },
    };

    event.waitUntil(self.registration.showNotification(title, options));
  } catch (error) {
    console.error('[SW] Error parsing push data', error);
  }
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const urlToOpen = event.notification.data.url;

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windowClients) => {
      // If window is already open, focus it and navigate
      for (let i = 0; i < windowClients.length; i++) {
        const client = windowClients[i];
        if (client.url.includes(self.registration.scope) && 'focus' in client) {
          client.navigate(urlToOpen);
          return client.focus();
        }
      }
      // Otherwise open a new window
      if (self.clients.openWindow) {
        return self.clients.openWindow(urlToOpen).then(() => {}) as any;
      }
      return Promise.resolve() as any;
    })
  );
});
